"""Support (donations), Contests (+ official rules), Join (hiring), Partner (sponsorship/advertising)."""
from kit import page, page_hero, article, faq, lead_band, e, PARTNER_URL

HP = '<input class="hp" type="text" name="_honey" tabindex="-1" autocomplete="off" aria-hidden="true">'


def build():
    # ------------------------------------------------------------ SUPPORT / DONATE
    fq, fs = faq([("Is my donation tax-deductible?", "High.School is not currently a registered charity, so donations are not tax-deductible. They directly fund the site’s operations, content and student prizes."),
                  ("Can my business sponsor instead?", "Yes — sponsorships come with recognition on contests, tools or newsletters. See <a href='../partner/'>Advertise & Partner</a>."),
                  ("Can I give in another way?", "Absolutely: share High.School with a student or teacher, report errors, contribute a guide, or volunteer as a student ambassador.")])
    body = page_hero("Support High.School", "High.School is free for every student. Your support keeps it that way — and funds new guides, tools, student contests and the people who build them.", [("Support Us", "")], meta=False, eyebrow="Reader-supported")
    body += f'''<div class="wrap"><div class="layout"><div>
<div class="tool" id="donate-tool"><h2 style="margin-top:0">Choose your support</h2>
<div class="toggle" role="group" aria-label="Frequency"><button type="button" class="active">One-time</button><button type="button">Monthly</button></div>
<div class="tiers" style="margin-top:14px"><button type="button" class="tier" data-amt="5"><b>$5</b><span class="small">Buys a student a study guide</span></button><button type="button" class="tier active" data-amt="15"><b>$15</b><span class="small">Funds a new practice quiz</span></button><button type="button" class="tier" data-amt="50"><b>$50</b><span class="small">Adds to a contest prize</span></button><button type="button" class="tier" data-amt="100"><b>$100</b><span class="small">Sponsors a new tool feature</span></button></div>
<div class="field" style="margin-top:12px"><label for="dn-custom">Or enter a custom amount (USD)</label><input id="dn-custom" type="number" min="1" placeholder="e.g. 25"></div>
<p style="font-size:1.1rem">You’re giving <strong id="dn-label">$15</strong></p>
<div style="display:flex;gap:10px;flex-wrap:wrap"><a href="#pledge" class="btn btn-primary" data-pay="paypal">Donate with PayPal</a><a href="#pledge" class="btn btn-ink" data-pay="stripe">Donate by card</a><a href="#pledge" class="btn btn-hl" data-pay="bmc">☕ Buy us a coffee</a></div>
<p class="small muted" style="margin-top:8px">Secure payments are processed by the provider you choose. We never see or store card details.</p></div>
<h2>Where your money goes</h2><div class="alloc card"><div><span>Operations & hosting</span><i style="width:30%"></i><b>30%</b></div><div><span>Promotion & marketing</span><i style="width:20%;background:var(--violet)"></i><b>20%</b></div><div><span>Hiring writers, tutors & creators</span><i style="width:30%;background:var(--coral)"></i><b>30%</b></div><div><span>Contest prizes</span><i style="width:20%;background:var(--hl)"></i><b>20%</b></div></div>
<p class="small muted">Target allocation; we publish an annual summary of how support was spent.</p>
<h2 id="pledge">Pledge form</h2><p>Prefer an invoice, bank transfer or a larger gift — or want to sponsor a specific prize? Send a pledge and we’ll reply with secure payment details.</p>
<div class="card"><form class="form" data-form data-thanks="thank-you/"><input type="hidden" name="_subject" value="Donation pledge — High.School">{HP}<input type="hidden" id="dn-amount" name="Amount (USD)" value="15"><input type="hidden" id="dn-freq-field" name="Frequency" value="One-time">
<div class="row2"><div class="field"><label for="p-name">Name</label><input id="p-name" name="Name" type="text" required></div><div class="field"><label for="p-email">Email</label><input id="p-email" name="Email" type="email" required></div></div>
<div class="row2"><div class="field"><label for="p-pref">Payment preference</label><select id="p-pref" name="Payment preference"><option value="paypal">PayPal</option><option value="stripe">Card</option><option value="bmc">Buy Me a Coffee</option><option>Bank transfer / invoice</option></select></div>
<div class="field"><label for="p-fund">Direct my gift to</label><select id="p-fund" name="Designation"><option>Where it’s needed most</option><option>Operations</option><option>Promotion & marketing</option><option>Hiring talent</option><option>Contest prizes</option></select></div></div>
<div class="field"><label for="p-msg">Message (optional)</label><textarea id="p-msg" name="Message"></textarea></div>
<label class="check"><input type="checkbox" name="Public recognition" value="Yes"><span>You may thank me publicly on the supporters list.</span></label>
<label class="check"><input type="checkbox" name="Adult confirmation" value="Yes" required><span>I am 18 or older (or a parent/guardian giving on a student’s behalf).</span></label>
<button class="btn btn-primary" type="submit">Send my pledge</button><p class="form-status" aria-live="polite"></p></form></div>
<h2>Other ways to help</h2><div class="grid g3"><div class="card"><h3>📣 Share</h3><p>Send a tool to a friend, post it in a class group chat, or tell your counselor.</p></div><div class="card"><h3>✍️ Contribute</h3><p>Write or review a guide. <a href="@@/join/">Join the team</a>.</p></div><div class="card"><h3>🏢 Sponsor</h3><p>Businesses can sponsor contests and tools. <a href="@@/partner/">Learn more</a>.</p></div></div>
<div class="prose">{fq}</div></div>
<aside><div class="aside-sticky"><div class="aside-box"><h4>💛 Why give?</h4><p class="small">Every guide and tool on High.School is free, with no paywalls and no sign-ups. Ads cover part of the cost; supporters cover the rest and fund student prizes.</p></div><div class="aside-box"><h4>🏆 Sponsor a prize</h4><p class="small">Fund a named award in our <a href="@@/contests/">student contests</a>.</p></div></div></aside></div></div>'''
    page("support/", "Support High.School — Donate", "Donate to keep High.School free for every student. Support operations, promotion, hiring talent and student contest prizes — one-time or monthly.", body, [("Support Us", "")], fs, "donate, support education, sponsor student prize", tools=True, noslide=True)

    # ------------------------------------------------------------ CONTESTS
    contests = [("✍️", "Essay Challenge", "Write 500–800 words responding to a prompt about learning, community or the future.", "Writing · Grades 9–12"),
                ("🔬", "STEM Explainer Video", "Explain a science or math concept in a 2–3 minute video anyone can understand.", "STEM · Grades 9–12"),
                ("🧮", "Math Problem-Solving Sprint", "A timed set of creative problems — from algebra to probability — with full solutions afterward.", "Math · Grades 9–12"),
                ("🎨", "Design & Art Prize", "Create a poster, illustration or digital design on a theme announced each round.", "Arts · Grades 9–12")]
    cards = "".join(f'<div class="card"><div class="ico">{i}</div><span class="tag new">Pre-registration open</span><h3 style="margin-top:8px">{t}</h3><p>{d}</p><p class="small muted" style="margin-top:8px">{m}</p></div>' for i, t, d, m in contests)
    body = page_hero("Student Contests & Prizes", "Compete, create and get recognized. High.School contests are free to enter and funded by sponsors and supporters.", [("Contests", "")], meta=False, eyebrow="Free to enter · Ages 13+")
    body += f'''<div class="wrap"><section><div class="grid g4">{cards}</div></section>
<section><div class="grid g2"><div class="prose"><h2>How it works</h2><ol><li><strong>Pre-register</strong> below — we’ll email you when a round opens with the prompt, dates and prize pool.</li><li><strong>Create</strong> your entry during the round (usually 3–4 weeks).</li><li><strong>Judging</strong> by a panel of educators using published criteria: originality, clarity, accuracy and impact.</li><li><strong>Winners</strong> are announced on this page and receive prizes funded by that round’s sponsors and supporters.</li></ol>
<p>Each round’s prize pool is confirmed and published before the round opens — we never announce a prize that isn’t funded. Entry is always free; no purchase necessary. Read the <a href="@@/contests/official-rules/">official rules</a>.</p>
<h2>Sponsor a round</h2><p>Brands, foundations and schools can fund a named prize and reach motivated students and families. <a href="@@/partner/">Become a sponsor</a> or <a href="@@/support/">donate to the prize fund</a>.</p></div>
<div class="card"><h3 style="margin-top:0">Pre-register for the next round</h3><form class="form" data-form data-thanks="thank-you/"><input type="hidden" name="_subject" value="Contest pre-registration — High.School">{HP}
<div class="field"><label for="ct-which">Contest(s)</label><select id="ct-which" name="Contest" required><option value="">Choose…</option><option>Essay Challenge</option><option>STEM Explainer Video</option><option>Math Problem-Solving Sprint</option><option>Design & Art Prize</option><option>All contests</option></select></div>
<div class="row2"><div class="field"><label for="ct-name">First name</label><input id="ct-name" name="Name" type="text" required></div><div class="field"><label for="ct-email">Email</label><input id="ct-email" name="Email" type="email" required></div></div>
<div class="row2"><div class="field"><label for="ct-grade">Grade</label><select id="ct-grade" name="Grade" required><option value="">Choose…</option><option>9</option><option>10</option><option>11</option><option>12</option></select></div><div class="field"><label for="ct-country">Country</label><input id="ct-country" name="Country" type="text" required></div></div>
<div class="field"><label for="ct-age">I am</label><select id="ct-age" name="I am" required><option value="">Choose…</option><option>Student 13–17</option><option>Student 18+</option><option>Parent / guardian registering a student</option><option>Under 13</option></select></div>
<div class="field"><label for="ct-pg">Parent/guardian email (required for students under 18)</label><input id="ct-pg" name="Guardian email" type="email"></div>
<label class="check"><input type="checkbox" name="Rules accepted" value="Yes" required><span>I have read the <a href="@@/contests/official-rules/">official rules</a>. If I’m under 18, my parent/guardian has approved my registration.</span></label>
<button class="btn btn-primary" type="submit">Pre-register free</button><p class="form-status" aria-live="polite"></p></form></div></div></section>
<section class="prose narrow"><h2>Winners archive</h2><p>Our first winners will be featured here, with their permission and their parent/guardian’s permission for students under 18.</p></section></div>'''
    page("contests/", "Student Contests & Prizes for High Schoolers", "Free contests for high school students — essay, STEM video, math and design challenges with sponsor-funded prizes. Pre-register for the next round.", body + lead_band("Building your activities list?", "Contests are great extracurriculars. Get a free match for essay coaching or college counseling.", "College counseling"), [("Contests", "")], keywords="high school contests, essay contest, stem competition, student prizes", noslide=True)

    rules = '''<p><strong>NO PURCHASE OR PAYMENT OF ANY KIND IS NECESSARY TO ENTER OR WIN. VOID WHERE PROHIBITED.</strong> These rules apply to every High.School contest round unless a round’s announcement states additional terms, which will be published before the round opens.</p>
<h2>1. Sponsor</h2><p>Each round is administered by High.School (“Administrator”). Funding sponsors for a round, if any, are named in that round’s announcement.</p>
<h2>2. Eligibility</h2><p>Open to students enrolled in grades 9–12 (or the international equivalent) or in a recognized homeschool or online high school program, who are at least 13 years old at the time of entry. Entrants under the age of majority in their jurisdiction must have permission from a parent or legal guardian, who may be required to sign prize documents. Employees of the Administrator and round sponsors and their immediate families are not eligible. Residents of jurisdictions where the contest is prohibited or restricted are not eligible.</p>
<h2>3. Entry period</h2><p>Each round’s start and end dates and time zone are published in the round announcement. Late entries are not accepted.</p>
<h2>4. How to enter</h2><p>Follow the round instructions, which may include submitting an original work through the entry form. Limit one entry per person per round unless stated otherwise. Entries must be the entrant’s own original work, must not infringe anyone’s rights, and must follow any word or time limits. Use of AI tools is governed by the round announcement; undisclosed AI-generated work may be disqualified.</p>
<h2>5. Judging</h2><p>Entries are judged by a panel selected by the Administrator using the criteria published for the round (for example originality, clarity, accuracy and impact). Judges’ decisions are final. If no entry meets minimum standards, the Administrator may decline to award a prize.</p>
<h2>6. Prizes</h2><p>The prize(s), approximate retail value and number of winners for each round are published before the round opens, and only funded prizes are announced. Prizes are non-transferable; no substitution except by the Administrator, who may substitute a prize of equal or greater value. Winners are responsible for any applicable taxes. Prize delivery may require completing an affidavit of eligibility and a publicity release (signed by a parent/guardian for minors).</p>
<h2>7. Winner notification</h2><p>Potential winners are notified by email (and, for minors, through the parent/guardian email provided) within 30 days of the round’s close. If a potential winner cannot be reached within 14 days or does not return required documents, an alternate may be selected.</p>
<h2>8. License to entries</h2><p>Entrants keep ownership of their work. By entering, entrants grant the Administrator a non-exclusive, royalty-free license to display the entry and the entrant’s first name, grade and region on High.School and its channels in connection with the contest, with parent/guardian permission for minors.</p>
<h2>9. Privacy</h2><p>Personal information is used only to administer the contest and as described in our <a href="@@/privacy/">Privacy Policy</a>. We do not sell entrant information.</p>
<h2>10. General conditions</h2><p>The Administrator may cancel, modify or suspend a round if fraud, technical failure or any other factor impairs its integrity, and may disqualify anyone who tampers with entry or violates these rules. The Administrator is not responsible for lost, late, incomplete or misdirected entries.</p>
<h2>11. Limitation of liability</h2><p>To the extent permitted by law, entrants release the Administrator and sponsors from liability arising from participation or acceptance and use of a prize.</p>
<h2>12. Governing law & disputes</h2><p>These rules are governed by the laws of the jurisdiction stated in the round announcement. Questions? <a href="@@/contact/">Contact us</a>.</p>
<h2>13. Winners list</h2><p>Winners are posted on the <a href="@@/contests/">contests page</a> after each round.</p>'''
    page("contests/official-rules/", "Contest Official Rules", "Official rules for High.School student contests: eligibility, entry, judging, prizes, winner notification, privacy and general conditions.",
         article("Contest Official Rules", "The rules that apply to every High.School contest round.", [("Contests", "@@/contests/"), ("Official Rules", "")], rules, [("Contests", "@@/contests/"), ("Privacy Policy", "@@/privacy/"), ("Terms of Use", "@@/terms/")], "Contest rules"), [("Contests", "@@/contests/"), ("Official Rules", "")], noslide=True)

    # ------------------------------------------------------------ JOIN / HIRING
    roles = [("✍️", "Content Writers & Editors", "Write and fact-check study guides, test-prep explainers and college articles.", "Remote · Contract · 18+"),
             ("👩‍🏫", "Subject-Matter Reviewers", "Teachers and tutors who review guides and practice questions for accuracy.", "Remote · Per review · 18+"),
             ("🎬", "Video Creators", "Produce short explainer videos and study-with-me content.", "Remote · Project-based · 18+"),
             ("📘", "Tutors & Counselors", "Join our partner network to receive matched student requests.", "Remote / local · 18+"),
             ("💻", "Developers & Designers", "Build new tools, improve accessibility and performance.", "Remote · Contract · 18+"),
             ("📣", "Student Ambassadors", "Share High.School at your school, give feedback and help run contests. Great for your activities list.", "Volunteer · Ages 13+ with guardian approval"),
             ("📈", "Growth & Partnerships", "Grow sponsorships, school partnerships and community outreach.", "Remote · Commission/contract · 18+")]
    cards = "".join(f'<div class="card"><div class="ico s">{i}</div><h3>{t}</h3><p>{d}</p><p class="small muted" style="margin-top:8px">{m}</p></div>' for i, t, d, m in roles)
    body = page_hero("Join the High.School Team", "We’re building the best free resource for high school — and we’re looking for writers, reviewers, creators, tutors, developers and student ambassadors.", [("Join the Team", "")], meta=False, eyebrow="Now hiring · Remote-first")
    body += f'''<div class="wrap"><section><div class="grid g3">{cards}</div></section>
<section><div class="grid g2"><div class="prose"><h2>Why work with us</h2><ul><li>Remote, flexible work with real impact on students</li><li>Your name on published work (writers, reviewers, creators)</li><li>Paid roles for adults; recognition, references and leadership experience for student ambassadors</li><li>Help shape new tools and features</li></ul>
<h2>How hiring works</h2><ol><li>Apply with the form — include a portfolio or sample if you have one.</li><li>Short paid trial task for contract roles.</li><li>Onboarding with our editorial and accessibility guidelines.</li></ol>
<p class="small muted">We are an equal-opportunity collaborator. Minors may apply only for volunteer ambassador roles, with parent/guardian approval.</p></div>
<div class="card"><h3 style="margin-top:0">Apply</h3><form class="form" data-form data-thanks="thank-you/"><input type="hidden" name="_subject" value="Job application — High.School">{HP}
<div class="field"><label for="j-role">Role</label><select id="j-role" name="Role" required><option value="">Choose…</option>{"".join(f"<option>{t}</option>" for _, t, _, _ in roles)}</select></div>
<div class="row2"><div class="field"><label for="j-name">Full name</label><input id="j-name" name="Name" type="text" required></div><div class="field"><label for="j-email">Email</label><input id="j-email" name="Email" type="email" required></div></div>
<div class="row2"><div class="field"><label for="j-loc">Location / time zone</label><input id="j-loc" name="Location" type="text" required></div><div class="field"><label for="j-hrs">Availability</label><select id="j-hrs" name="Availability"><option>A few hours a week</option><option>Part-time</option><option>Project-based</option><option>Full-time</option></select></div></div>
<div class="field"><label for="j-url">Portfolio, LinkedIn or sample link</label><input id="j-url" name="Portfolio" type="url" placeholder="https://"></div>
<div class="field"><label for="j-age">Age</label><select id="j-age" name="I am" required><option value="">Choose…</option><option>18 or older</option><option>Student 13–17 (ambassador only)</option><option>Under 13</option></select></div>
<div class="field"><label for="j-msg">Why you? (a few sentences)</label><textarea id="j-msg" name="Message" required></textarea></div>
<label class="check"><input type="checkbox" name="Consent" value="Yes" required><span>I agree to be contacted about this application. If I’m under 18, my parent/guardian approves.</span></label>
<button class="btn btn-primary" type="submit">Submit application</button><p class="form-status" aria-live="polite"></p></form></div></div></section></div>'''
    page("join/", "Join the Team: Writers, Tutors, Creators & Ambassadors", "Work with High.School: remote roles for content writers, subject reviewers, video creators, tutors, developers and growth — plus volunteer student ambassadors.", body, [("Join the Team", "")], keywords="education jobs remote, tutor jobs, content writer education, student ambassador", noslide=True)

    # ------------------------------------------------------------ PARTNER / ADVERTISE
    pk = [("🏆", "Contest Sponsorship", "Fund a named prize and get brand placement on contest pages, emails and winner announcements.", ["Named award", "Logo on contest pages", "Winner spotlight"]),
          ("🧮", "Tool Sponsorship", "“Presented by” placement on a high-traffic calculator such as the GPA calculator.", ["Exclusive placement", "Category exclusivity", "Monthly reporting"]),
          ("📬", "Newsletter Sponsorship", "Reach students, parents and educators in the Weekly Study Pack.", ["Native sponsor slot", "Audience segment options", "Click reporting"]),
          ("🤝", "Lead Partnerships", "For tutoring, test-prep, counseling and accredited online schools: receive opted-in, qualified requests.", ["Consent-based leads", "Filters by need & region", "CPL or rev-share"]),
          ("📚", "Content Partnerships", "Co-create guides, webinars or resources with clear labeling.", ["Co-branded resources", "Expert bylines", "Webinar hosting"]),
          ("🌐", "Domain & Website", "Interested in acquiring or partnering on the High.School domain or website?", ["Confidential inquiry", "Strategic partnerships", "Via web.works"])]
    cards = "".join(f'<div class="card plan"><div class="ico v">{i}</div><h3>{t}</h3><p>{d}</p><ul>' + "".join(f"<li>{x}</li>" for x in xs) + "</ul></div>" for i, t, d, xs in pk)
    body = page_hero("Advertise, Sponsor & Partner", "Reach a high-intent audience of high school students (13+), parents, adult learners and educators — with transparent, student-safe placements.", [("Partner", "")], meta=False, eyebrow="Sponsorship · Advertising · Partnerships")
    body += f'''<div class="wrap"><section><div class="band band-hl" style="text-align:center"><h2>Interested in this website, domain name, sponsorship, advertisement or partnership?</h2><p>For the fastest response, contact us through web.works.</p><a class="btn btn-ink" href="{PARTNER_URL}" target="_blank" rel="noopener">Contact via web.works →</a></div></section>
<section><div class="grid g3">{cards}</div></section>
<section><div class="grid g2"><div class="prose"><h2>Our standards</h2><ul><li>All sponsored content is clearly labeled.</li><li>No ads or partners in categories inappropriate for teens (alcohol, tobacco/vaping, gambling, dating, weight-loss, predatory lending).</li><li>Lead partners must honor consent and never contact minors without a parent/guardian.</li><li>Sponsors never influence editorial guides or rankings.</li></ul>
<h2>Audience</h2><p>Students 13–18, parents and guardians, adult learners completing diplomas, and teachers and counselors — primarily from the United States, Canada, the UK and India.</p></div>
<div class="card"><h3 style="margin-top:0">Partnership inquiry</h3><form class="form" data-form data-thanks="thank-you/"><input type="hidden" name="_subject" value="Partnership inquiry — High.School">{HP}
<div class="row2"><div class="field"><label for="pt-name">Name</label><input id="pt-name" name="Name" type="text" required></div><div class="field"><label for="pt-email">Work email</label><input id="pt-email" name="Email" type="email" required></div></div>
<div class="row2"><div class="field"><label for="pt-org">Organization</label><input id="pt-org" name="Organization" type="text" required></div><div class="field"><label for="pt-web">Website</label><input id="pt-web" name="Website" type="url" placeholder="https://"></div></div>
<div class="row2"><div class="field"><label for="pt-type">Interest</label><select id="pt-type" name="Interest" required><option value="">Choose…</option>{"".join(f"<option>{t}</option>" for _, t, _, _ in pk)}<option>Advertising (display)</option><option>Other</option></select></div>
<div class="field"><label for="pt-budget">Budget range</label><select id="pt-budget" name="Budget"><option>Not sure yet</option><option>Under $1,000</option><option>$1,000–$5,000</option><option>$5,000–$25,000</option><option>$25,000+</option></select></div></div>
<div class="field"><label for="pt-msg">Goals & timing</label><textarea id="pt-msg" name="Message" required></textarea></div>
<button class="btn btn-primary" type="submit">Send inquiry</button><p class="form-status" aria-live="polite"></p></form></div></div></section></div>'''
    page("partner/", "Advertise, Sponsor & Partner with High.School", "Sponsor student contests and tools, advertise in our newsletter, become a lead partner, or inquire about the High.School domain and website.", body, [("Partner", "")], keywords="advertise to high school students, education sponsorship, education lead partners", noslide=True)
